[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static Query defaultCTQuery()
{
    Query vendVendorV2Query = new Query();

    var vendTableDS = vendVendorV2Query.addDataSource(tableNum(VendTable));

    var vendInvoiceDeclaration_ISDS = vendTableDS.addDataSource(tableNum(VendInvoiceDeclaration_IS));
    vendInvoiceDeclaration_ISDS.joinMode(JoinMode::OuterJoin);
    vendInvoiceDeclaration_ISDS.relations(true);

    // DirPartyBaseEntity
    var qbdDirParty =  DirPartyBaseEntity::addChangeTrackingDataSourcesForPartyBase(vendTableDS, fieldNum(VendTable, Party));
    // DirPartyBaseEntity related datasources
    //---LogisticsPostalAddressBaseEntity
    LogisticsPostalAddressBaseEntityChangeTrackingHelper::addPostalAddressBasedOnPrimaryAddressLocation(qbdDirParty, fieldNum(DirPartyTable, PrimaryAddressLocation));

    var purchJournalAutoSummaryDS = vendTableDS.addDataSource(tableNum(PurchJournalAutoSummary));
    purchJournalAutoSummaryDS.joinMode(JoinMode::OuterJoin);
    purchJournalAutoSummaryDS.addLink(fieldNum(VendTable, AccountNum), fieldNum(PurchJournalAutoSummary, VendAccount));

    var vend1099OIDDetailDS = vendTableDS.addDataSource(tableNum(Vend1099OIDDetail));
    vend1099OIDDetailDS.joinMode(JoinMode::OuterJoin);
    vend1099OIDDetailDS.addLink(fieldNum(VendTable, AccountNum), fieldNum(Vend1099OIDDetail, VendTable));

    var taxInformationVendTable_INDS = vendTableDS.addDataSource(tableNum(TaxInformationVendTable_IN));
    taxInformationVendTable_INDS.joinMode(JoinMode::OuterJoin);
    taxInformationVendTable_INDS.addLink(fieldNum(VendTable, AccountNum), fieldNum(TaxInformationVendTable_IN, VendTable));

    var vendInfoZakat_SADS = vendTableDS.addDataSource(tableNum(VendInfoZakat_SA));
    vendInfoZakat_SADS.joinMode(JoinMode::OuterJoin);
    vendInfoZakat_SADS.addLink(fieldNum(VendTable, AccountNum), fieldNum(VendInfoZakat_SA, VendAccount));

    return vendVendorV2Query;
}

    public static container getEntityDataSourceToFieldMapping(container mapping)
    {
        // Any adjustments to this mapping can impact the logic in the IBusinessEventsTableToEntityRecordIdSelector implementations.
        // Verify any changes made against those implementations as they may have a dependency on the context provided.
        mapping += [[tablestr(DirPartyBaseEntity), tablenum(LogisticsPostalAddress), fieldstr(VendVendorV2Entity, AddressRecordId)],
                    [identifierstr(DirPartyBaseEntity), tablenum(LogisticsElectronicAddress), fieldstr(VendVendorV2Entity, PrimaryContactURLRecordId)],
                    [identifierstr(DirPartyBaseEntity1), tablenum(LogisticsElectronicAddress), fieldstr(VendVendorV2Entity, PrimaryContactPhoneRecordId)],
                    [identifierstr(DirPartyBaseEntity2), tablenum(LogisticsElectronicAddress), fieldstr(VendVendorV2Entity, PrimaryContactEmailRecordId)],
                    [identifierstr(DirPartyBaseEntity3), tablenum(LogisticsElectronicAddress), fieldstr(VendVendorV2Entity, PrimaryContactFaxRecordId)]];

	    return mapping;
    }

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, DirPartyBaseEntity))
    {
        // Takes care of maintaining the reference to existing parties if this record provides a party number.
        DirPartyBaseEntity::initializeDirPartyBaseEntityDataSource(_entityCtx, _dataSourceCtx);
    }
}

public void initValue()
{
    if (!this.skipNumberSequenceCheck() && !VendGroup::doesAnyGroupHaveVendAccountNumberSequenceSet())
    {
        NumberSeqRecordFieldHandler::enableNumberSequenceControlForField(
            this, fieldNum(METSATVendVendorV2Entity, VendorAccountNumber), VendParameters::numRefVendAccount());
    }

    super();
}

public TableExtension getExtension()
{
    return SysTableExtension::construct();
}

public container getDefaultingDependencies()
{
    return  [[fieldNum(METSATVendVendorV2Entity, VendorAccountNumber)]];
}

    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        #ISOCountryRegionCodes
        boolean ret;

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, DirPartyBaseEntity))
        {
            DirPartyBaseEntityHelper partyHelper = new DirPartyBaseEntityHelper();

            // Coordinates saving between party and address entity datasources, the last parameter will let address entity create a new address for update.
            partyHelper.preUpdateEntityDataSource(_entityCtx, _dataSourceCtx,
                dataEntityDataSourceStr(METSATVendVendorV2Entity, LogisticsPostalAddressBaseEntity), NoYes::No);

            ret = partyHelper.validateNameFields(_dataSourceCtx);

            if (ret)
            {
                ret = super(_entityCtx, _dataSourceCtx);
            }

            if (ret)
            {
                var addressDataSource = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(METSATVendVendorV2Entity, LogisticsPostalAddressBaseEntity));
                partyHelper.postUpdateEntityDataSource(_entityCtx, _dataSourceCtx, addressDataSource.name());
                this.mapAddressDataSourceToEntity(_dataSourceCtx, addressDataSource);
            }
        }
        else if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, VendTable))
        {
            if (SysCountryRegionCode::isLegalEntityInCountryRegion([#isoMX]))
            {
                // Skip defaultRow in update to avoid override of entity fields
                _dataSourceCtx.skipDefaultRow(true);
            }
            VendTable vendTable = _dataSourceCtx.getBuffer();
			if (!vendTable.isFieldSet(fieldNum(VendTable, VendGroup)))
            {
                vendTable.fieldState(fieldNum(VendTable, TaxGroup), FieldState::Set);
            }

            ret = this.validateVendTableDataSource(_dataSourceCtx) && super(_entityCtx, _dataSourceCtx);
        }
        else
        {
            ret = super(_entityCtx, _dataSourceCtx);
        }

        return ret;
    }

    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean ret;

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, DirPartyBaseEntity))
        {
            DirPartyBaseEntityHelper partyHelper = new DirPartyBaseEntityHelper();
            partyHelper.preInsertEntityDataSource(_entityCtx, _dataSourceCtx,
                dataEntityDataSourceStr(METSATVendVendorV2Entity, LogisticsPostalAddressBaseEntity));

            ret = partyHelper.validateNameFields(_dataSourceCtx);

            if (ret)
            {
                ret = super(_entityCtx, _dataSourceCtx);
            }

            if (ret)
            {
                var addressDataSource = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(VendVendorV2Entity, LogisticsPostalAddressBaseEntity));
                partyHelper.postInsertEntityDataSource(_entityCtx, _dataSourceCtx, addressDataSource.name());
                this.mapAddressDataSourceToEntity(_dataSourceCtx, addressDataSource);
            }
        }
        else if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, VendTable))
		{
            ret = this.validateVendTableDataSource(_dataSourceCtx) && super(_entityCtx, _dataSourceCtx);
        }
        else
        {
            if (_dataSourceCtx.getBuffer().TableId == tableNum(PurchJournalAutoSummary)
                && _dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
            {
                // For performance reasons, skip the insert if the table value is the
                // default value:
                PurchJournalAutoSummary buffer = _dataSourceCtx.getBuffer();

                if (buffer.AutoSummary == NoYes::No)
                {
                    _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
                }
            }

            ret = super(_entityCtx, _dataSourceCtx);
        }

        return ret;
    }

private void mapAddressDataSourceToEntity(
    DataEntityDataSourceRuntimeContext _partyDataSourceCtx,
    DataEntityDataSourceRuntimeContext _addressDataSourceCtx)
{
    LogisticsPostalAddressBaseEntity addressEntity;

    DirPartyBaseEntity partyEntity = _partyDataSourceCtx.getBuffer();

    select addressEntity
        where addressEntity.LocationRecId == partyEntity.PrimaryAddressLocation;

    this.fromViewDataSource(_addressDataSourceCtx.id(), addressEntity);
}

public void persistEntity(DataEntityRuntimeContext _entityCtx)
{
    this.skipDataSourceValidateField(fieldNum(METSATVendVendorV2Entity, InvoiceVendorAccountNumber), true);

    if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
    {
        this.DefaultLedgerDimension = DimensionDefaultResolver::checkAndCreateSelfReference(tablenum(VendTable), this.VendorAccountNumber, this.DefaultLedgerDimensionDisplayValue);
    }

    super(_entityCtx);
}

private boolean validateVendTableDataSource(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;

    //if (strLen(this.InvoiceVendorAccountNumber) && this.VendorAccountNumber != this.InvoiceVendorAccountNumber)
    //{
    //    ret = _dataSourceCtx.getBuffer().validateField(fieldNum(Vendtable, InvoiceAccount));
    //}

    // updateEntityDataSource() failure does not prevent the datasource from being saved, unless it is an inner join
    // In case of update operation, throwing validation error is needed to cancel the update
    if (!ret && _dataSourceCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
    {
        _dataSourceCtx.throwValidateWriteFailed();
    }

    return ret;
}

/// <summary>
/// Resolve conflicts in the ordering of data import such that dependent records insert after parent records.
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">The execution context for import.</param>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    VendVendorV2Staging::resolveImportSequence(_dmfDefinitionGroupExecution);
}

/// <summary>
/// Resolve conflicts in the ordering of data import to not delete DirParty instead of Vendor.
/// </summary>
/// <param name = "_entityCtx">The context of the entity.</param>
/// <param name = "_dataSourceCtx">The context of the datasource being mapped.</param>
/// <returns>True if the database operation is successfully, false if it is not.</returns>
public boolean deleteEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    // Do not delete the DirParty directly - it will be deleted as part of vendor deletion.
    // This will ensure that the vendor is always deleted before DirParty.
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(METSATVendVendorV2Entity, VendTable):
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Delete);
            _dataSourceCtx.setDataSaved(false);
            break;

        case dataEntityDataSourceStr(METSATVendVendorV2Entity, DirPartyBaseEntity):
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
            _dataSourceCtx.setDataSaved(true);
            break;
    }

    ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
/// Maps the entity to corresponding datasources, including applications of change proposal functionality.
/// </summary>
/// <param name = "_entityCtx">The entity runtime context.</param>
/// <param name = "_dataSourceCtx">The datasource context.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, VendTable))
    {
        this.processChangesForApproval(_entityCtx);
    }
    else if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, DirPartyBaseEntity))
    {
        this.processChangesForApproval(_entityCtx);
    }

    super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METSATVendVendorV2Entity, LogisticsPostalAddressBaseEntity))
    {
        // The Address field is generated to a specified format based on the component address parts. Updating it directly is not allowed..
        _dataSourceCtx.getBuffer().fieldState(fieldNum(LogisticsPostalAddressBaseEntity, Address), FieldState::NotSet);
    }
}

/// <summary>
/// Validates the contents prior to writing it.
/// </summary>
/// <param name = "_entityCtx">The entity context, containing a database operation type.</param>
private void processChangesForApproval(DataEntityRuntimeContext _entityCtx)
{
    VendTableChangeProposalDataEntityBehavior selectedBehavior = VendParameters::find().ChangeProposalDataEntityBehavior;

    if (selectedBehavior == VendTableChangeProposalDataEntityBehavior::AllowWithoutApproval)
    {
        // Bypass all validation, since we elected not to restrict.
        return;

        // Doing this early exit for "allow without approval", which is the only entity behavior option where everything will be persisted as is,
        // allows us to assume we are dealing with a "reject" or "approval required" behavior, meaning
        // we can safely roll back the change-controlled field on the data entity if we detect a change.
    }

    if(_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
    {
        boolean controlledChangesMade = this.containsControlledChanges();

        if(!controlledChangesMade)
        {
            // Nothing to change, can early exit.
            // Can also assume if we don't hit this exit that a change request will be required.
            return;
        }

        if(selectedBehavior == VendTableChangeProposalDataEntityBehavior::RejectChanges)
        {
            // Making changes while settings require us to reject changes.
            throw error("@AccountsPayable:VendChangeProposal_CannotBeChangedFromDE");
        }

        VendTable vend = VendTable::find(this.VendorAccountNumber);
        RecId vendRecId = vend.RecId;

        if (!vendRecId)
        {
            // We are trying to update a record that does not exist.
            throw error(Error::wrongUseOfFunction(funcName()));
        }

        if (!vend.canModifyChangeProposal())
        {
            // Changes are made to controlled fields, but the vendor is not in a position to accept them
            // due to an existing set of pending changes.
            throw error("@AccountsPayable:VendTableChangeProposal_ChangesNotAllowed");
        }

        // If we got this far without early exiting or throwing, then we must apply the changes.
        VendTableChangeProposal change = VendTableChangeProposal::findOrCreateAutogenerated(vendRecId, true);

        this.initializeVendTableChangeProposal(change);

        ttsbegin;
        change.update();
        ttscommit;
    }

}

