/// <summary>
/// Checks whether the data entity is trying to make changes on fields which are change-controlled.
/// </summary>
/// <returns>True if such changes are being made; false otherwise.</returns>
protected boolean containsControlledChanges()
{
    boolean result = 
        (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::Name)
            && this.VendorOrganizationName != this.orig().VendorOrganizationName)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::BankAccount)
            && this.BankAccountId != this.orig().BankAccountId)

    //|| (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::CashDisc)
    //        && this.CashDiscountCode != this.orig().CashDiscountCode)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::CreditMax)
            && this.CreditLimit != this.orig().CreditLimit)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::CreditRating)
            && this.CreditRating != this.orig().CreditRating)

    //|| (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::InvoiceAccount)
    //        && this.InvoiceVendorAccountNumber != this.orig().InvoiceVendorAccountNumber)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::PaymMode)
            && this.DefaultVendorPaymentMethodName != this.orig().DefaultVendorPaymentMethodName)

    //|| (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::PaymSpec)
    //        && this.PaymentSpecificationId != this.orig().PaymentSpecificationId)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::PaymTermId)
            && this.DefaultPaymentTermsName != this.orig().DefaultPaymentTermsName)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::VATNum)
            && this.TaxExemptNumber != this.orig().TaxExemptNumber)

    || (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::VendGroup)
            && this.VendorGroupId != this.orig().VendorGroupId);

    //|| (VendTableChangeProposalFieldEnablement::isEnabledFor(VendTableChangeProposalField::VendPriceToleranceGroupId)
    //        && this.VendorPriceToleranceGroupId != this.orig().VendorPriceToleranceGroupId

    return result;
}

/// <summary>
/// Defaults the vendor party type when a matching vendor party number is not found.
/// Generate number sequence and assign vendor account number (if not manual), when previously delayed
/// </summary>
public void defaultRow()
{
    if (!this.skipNumberSequenceCheck() && VendGroup::doesAnyGroupHaveVendAccountNumberSequenceSet())
    {
        VendGroup vendGroup = VendGroup::find(this.VendorGroupId);

        RefRecId numberSequenceRecId = vendGroup.VendAccountNumSeq ? 
            vendGroup.VendAccountNumSeq : VendParameters::numRefVendAccount().NumberSequenceId;

        //CustVendNumberSeqHandler::enableNumberSequenceControl(this, fieldNum(METSATVendVendorV2Entity, VendorAccountNumber), numberSequenceRecId);
    }

    if (this.VendorPartyType == '' && !DirPartyTable::find(this.VendorPartyNumber))
    {
        switch (DirAppParameters::defaultPartyType(tableNum(VendTable)))
        {
            case DirPartyBaseType::Organization:
                this.VendorPartyType = DirUtility::PARTYTYPE_ORGANIZATION;
                break;

            case DirPartyBaseType::Person:
                this.VendorPartyType = DirUtility::PARTYTYPE_PERSON;
                break;
        }
    }

    super();
}

