    LogisticsAddressCountryRegionTranslation::replaceAddressTokenByFieldName(this, fieldStr(METSATVendVendorV2Entity, FormattedPrimaryAddress), fieldStr(VendVendorV2Entity, AddressCountryRegionId));
}

